glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif
void main () {
    vec4 pos = vec4(a_position, 1.0);
    #if CC_USE_MODEL
        pos = cc_matViewProj * cc_matWorld * pos;
    #else
        pos = cc_matViewProj * pos;
    #endif
    #if USE_TEXTURE
        v_uv0 = a_uv0;
    #endif
    gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif
uniform Params {
    vec4 tintColor;
    vec4 effectParams;
};
void main () {
    vec4 tex = vec4(1.0);
    #if USE_TEXTURE
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    tex.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    tex.a *= texture_tmp.a;
  #else
    tex *= texture_tmp;
  #endif
    #endif
float brightness = effectParams.x;
float mask = tex.r;
vec3 color = tintColor.rgb * mask;
color += brightness * mask;
color = clamp(color, 0.0, 1.0);
    gl_FragColor = vec4(
        color,
        tex.a
    );
}

glsl1.vert:
precision highp float;
uniform mat4 cc_matViewProj;
uniform mat4 cc_matWorld;
attribute vec3 a_position;
#if USE_TEXTURE
attribute vec2 a_uv0;
varying vec2 v_uv0;
#endif
void main () {
    vec4 pos = vec4(a_position, 1.0);
    #if CC_USE_MODEL
        pos = cc_matViewProj * cc_matWorld * pos;
    #else
        pos = cc_matViewProj * pos;
    #endif
    #if USE_TEXTURE
        v_uv0 = a_uv0;
    #endif
    gl_Position = pos;
}

glsl1.frag:
precision highp float;
#if USE_TEXTURE
varying vec2 v_uv0;
uniform sampler2D texture;
#endif
uniform vec4 tintColor;
uniform vec4 effectParams;
void main () {
    vec4 tex = vec4(1.0);
    #if USE_TEXTURE
  vec4 texture_tmp = texture2D(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture2D(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    tex.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    tex.a *= texture_tmp.a;
  #else
    tex *= texture_tmp;
  #endif
    #endif
float brightness = effectParams.x;
float mask = tex.r;
vec3 color = tintColor.rgb * mask;
color += brightness * mask;
color = clamp(color, 0.0, 1.0);
    gl_FragColor = vec4(
        color,
        tex.a
    );
}
